let rawData = $input.first().json;
let payload = rawData;

// Kiểm tra xem dữ liệu có bị bọc trong trường "message" của MQTT không
if (rawData.message) {
  // Nếu message đang là chuỗi Text (String), ta ép nó thành dạng JSON (Object)
  if (typeof rawData.message === 'string') {
    payload = JSON.parse(rawData.message);
  } else {
    payload = rawData.message;
  }
}

// Lúc này payload đã là một Object chuẩn: {"time": "...", "gh_temp": ...}
const timeString = payload.time;

// Cắt lấy phần ngày (10 ký tự đầu tiên: YYYY-MM-DD)
const created_date = timeString.substring(0, 10);

// Tạo các trường mới theo đúng format database của bạn
payload.created = timeString;
payload.created_date = created_date;

return [{ json: payload }];

