// Lấy nội dung văn bản từ AI Agent (Groq)
const aiOutput = $input.first().json.output;

try {
  // Tìm kiếm đoạn JSON trong văn bản bằng Regex
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);

  if (!jsonMatch) {
    throw new Error("Không tìm thấy dữ liệu JSON trong phản hồi của AI.");
  }

  // Chuyển đổi chuỗi thành Object JSON
  const result = JSON.parse(jsonMatch[0]);

  // Trả về dữ liệu đã parse kèm theo dữ liệu gốc (nếu cần dùng tiếp)
  return [{
    json: {
      ...result,
      original_data: $input.first().json
    }
  }];
} catch (error) {
  // Trường hợp AI trả về format lỗi
  return [{
    json: {
      status: "error",
      reason: "AI output parsing failed",
      raw_output: aiOutput
    }
  }];
}

// 1. Lấy nội dung tin nhắn người dùng vừa gõ trả lời
const text = $json.message?.text || "";
const chat_id = $json.message?.chat?.id;

// Loại bỏ icon "📤" ở đầu chuỗi (nếu người dùng lỡ copy vào) và xóa khoảng trắng
const cleanText = text.replace('📤', '').trim();

// 2. Cắt tin nhắn ra bằng dấu phẩy "," và xóa khoảng trắng thừa ở các phần tử
const parts = cleanText.split(',').map(item => item.trim());

// 3. Kiểm tra xem có đủ ít nhất 5 phần không (SP, Tiêu chuẩn, Đóng gói, SL, Vận chuyển)
if (parts.length >= 5) {
  // Tự tạo mã Lô chuyên nghiệp (Ví dụ: LOT-260306-1234)
  const dateStr = new Date().toISOString().slice(2, 10).replace(/-/g, ''); // Lấy định dạng YYMMDD
  const randomStr = Math.floor(1000 + Math.random() * 9000); // 4 số ngẫu nhiên
  const batchId = `LOT-${dateStr}-${randomStr}`;

  // Lấy giờ Việt Nam
  const thoigian = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

  // Gán 5 biến theo đúng thứ tự
  const sanpham = parts[0];     // VD: "Cà chua Beef"
  const tieuchuan = parts[1];   // VD: "VietGAP"
  const donggoi = parts[2];     // VD: "Thùng giấy sáp 10kg"
  const soluong = parts[3];     // VD: "2 tấn"
  const vanchuyen = parts[4];   // VD: "Xe tải 61C-123.45"

  // Định dạng dữ liệu nhúng vào QR Code (Dùng \n để xuống dòng cho đẹp khi quét)
  const qrRawData = `Mã lô: ${batchId}\nSản phẩm: ${sanpham}\nTiêu chuẩn: ${tieuchuan}\nĐóng gói: ${donggoi}\nSố lượng: ${soluong}\nVận chuyển: ${vanchuyen}\nNgày xuất: ${thoigian}`;

  // Mã hóa URL và tạo link ảnh QR Code
  const qrData = encodeURIComponent(qrRawData);
  const linkqr = `https://api.qrserver.com/v1/create-qr-code/?size=400x400&margin=10&data=${qrData}`;

  return { 
      IsValid: true,
      ChatID: chat_id,
      BatchID: batchId,
      SanPham: sanpham,
      TieuChuan: tieuchuan,
      DongGoi: donggoi,
      SoLuong: soluong,
      VanChuyen: vanchuyen,
      ThoiGian: thoigian,
      Link_QR: linkqr,
      Status: "Pending"
  };
} else {
  // Trả về lỗi nếu nhập thiếu dấu phẩy hoặc không đủ 5 trường
  return {
      IsValid: false,
      ChatID: chat_id,
      Message: "⚠️ Sai cú pháp! Vui lòng nhập đủ 5 thông tin ngăn cách bằng dấu phẩy.\n\n👉 *Ví dụ đúng:*\n`Cà chua Beef, VietGAP, Thùng giấy sáp 10kg, 2 tấn, Xe tải 61C-123.45`"
  };
}

// 1. Lấy dữ liệu từ API trả về
const detections = items[0].json.detections;
const base64String = items[0].json.image_base64;

// 2. Tạo nội dung tin nhắn báo cáo
