// Lấy toàn bộ dữ liệu từ node 'Read data1'
const rows = $('Read data1').all().map(i => i.json);

// Hàm tính trung bình (đã thêm tính năng làm tròn 2 chữ số thập phân cho gọn đẹp)
function avg(arr, key) {
  if (arr.length === 0) return 0; // Tránh lỗi chia cho 0 nếu không có dòng nào
  const sum = arr.reduce((sum, r) => sum + Number(r[key] || 0), 0);
  return Number((sum / arr.length).toFixed(2));
}

// Nếu không có dữ liệu trả về, báo đếm = 0
if (rows.length === 0) {
  return [{ json: { sample_count: 0, note: "Không có dữ liệu" } }];
}

return [
  {
    json: {
      sample_count: rows.length,

      // Sửa lại key cho khớp đúng với JSON (gh_temp, gh_hum)
      avg_temperature: avg(rows, "gh_temp"),
      avg_humidity: avg(rows, "gh_hum"),

      // Vì dữ liệu không có CO2, tôi thay bằng trung bình ánh sáng (gh_lux)
      avg_lux: avg(rows, "gh_lux"), 

      // Lấy giá trị lớn nhất / nhỏ nhất
      max_temperature: Math.max(...rows.map(r => Number(r.gh_temp))),
      min_humidity: Math.min(...rows.map(r => Number(r.gh_hum)))
    }
  }
];

